/**
 * Every image and film on the site, in one place.
 *
 * Renditions (sizes, blur placeholders, video paths) are generated by
 * scripts/media/build-almasi-media.mjs into media-data.json; the words — titles,
 * alt text, provenance — are written here by hand.
 *
 * Provenance is recorded honestly. `supplied` scenes are the developer's own
 * renders, retouched only to remove the marketing text baked into them.
 * `concept` scenes were generated in the same visual language to cover spaces
 * no render exists for yet. Both are CG and carry the artist's-impression note;
 * concept scenes are the first to replace when the architect's visualiser
 * delivers (docs/CONTENT_BRIEF.md lists them).
 */
import type { ResidenceType } from './residences';
import data from './media-data.json';

export type SceneId =
  | 'aerial'
  | 'street'
  | 'arrival'
  | 'lobby'
  | 'pool'
  | 'restaurant'
  | 'gym'
  | 'wellness'
  | 'cowork'
  | 'parking'
  | 'living-2br'
  | 'two-kitchen'
  | 'one-living'
  | 'one-bedroom'
  | 'one-kitchen'
  | 'ph-living'
  | 'ph-kitchen'
  | 'ph-bedroom'
  | 'ph-bath'
  | 'ph-terrace'
  | 'view'
  | 'plan-1br'
  | 'plan-2br'
  | 'plan-ph';

export type Provenance = 'supplied' | 'concept';

interface SceneWords {
  title: string;
  alt: string;
  provenance: Provenance;
  /** object-position for cover crops, so the subject survives a portrait screen. */
  focus?: string;
}

export interface Rendition {
  src: string;
  width: number;
  height: number;
  blur: string;
  video?: { hd: string; sd: string; poster: string; seconds: number };
}

export interface Scene extends SceneWords, Rendition {
  id: SceneId;
}

