const RENDITIONS = data as Partial<Record<SceneId, Rendition>>;

/** Scenes whose renditions exist. A missing one is a build step not run, not a crash. */
export function hasScene(id: SceneId): boolean {
  return RENDITIONS[id] !== undefined;
}

const FALLBACK: SceneId = 'street';

export function scene(id: SceneId): Scene {
  const rendition = RENDITIONS[id] ?? RENDITIONS[FALLBACK];
  if (!rendition) {
    throw new Error('No media renditions — run scripts/media/build-almasi-media.mjs');
  }
  return { id, ...WORDS[id], ...rendition };
}

